package com.bestpractice.api.app;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.extension.ExtendWith;
import static org.junit.jupiter.api.Assertions.assertThrows;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.InterceptorRegistration;
import springfox.documentation.spring.web.plugins.Docket;
import springfox.documentation.spi.DocumentationType;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AppBeanGeneratedAiTests {

    private AppBean.SwaggerConfig swaggerConfig;
    private AppBean.SwaggerConfig.WebMvcConfig webMvcConfig;
    private com.bestpractice.api.domain.component.RequestInfoComponent requestInfoComponent;
    private com.bestpractice.api.domain.component.AuthComponent authComponent;

    @BeforeEach
    void setUp() {
        requestInfoComponent = mock(com.bestpractice.api.domain.component.RequestInfoComponent.class);
        authComponent = mock(com.bestpractice.api.domain.component.AuthComponent.class);
        webMvcConfig = new AppBean.SwaggerConfig.WebMvcConfig();
        // Inject mocks via reflection since fields are autowired
        try {
            java.lang.reflect.Field requestInfoField = AppBean.SwaggerConfig.WebMvcConfig.class.getDeclaredField("requestInfo");
            requestInfoField.setAccessible(true);
            requestInfoField.set(webMvcConfig, requestInfoComponent);
            java.lang.reflect.Field authComponentField = AppBean.SwaggerConfig.WebMvcConfig.class.getDeclaredField("authComponent");
            authComponentField.setAccessible(true);
            authComponentField.set(webMvcConfig, authComponent);
        } catch (Exception e) {
            fail("Failed to inject mocks: " + e.getMessage());
        }
        swaggerConfig = new AppBean.SwaggerConfig();
    }

    @Test
    void givenWebMvcConfig_whenInterceptorControllerCalled_thenReturnsNonNullInstance() {
        // GIVEN - WebMvcConfig with mocked dependencies

        // WHEN - Calling interceptorController
        InterceptorController controller = webMvcConfig.interceptorController();

        // THEN - Verify non-null and correct type
        assertNotNull(controller);
        assertTrue(controller instanceof InterceptorController);
    }

    @Test
    void givenWebMvcConfig_whenAddInterceptorsCalled_thenRegistryReceivesInterceptor() {
        // GIVEN - Mock InterceptorRegistry and InterceptorRegistration
        InterceptorRegistry registry = mock(InterceptorRegistry.class);
        InterceptorRegistration registration = mock(InterceptorRegistration.class);
        when(registry.addInterceptor(any())).thenReturn(registration);
        when(registration.addPathPatterns(anyString())).thenReturn(registration);

        // WHEN - Calling addInterceptors
        webMvcConfig.addInterceptors(registry);

        // THEN - Verify addInterceptor and addPathPatterns were called
        verify(registry, times(1)).addInterceptor(any());
        verify(registration, times(1)).addPathPatterns("/api/**");
    }

    @Test
    void givenSwaggerConfig_whenSwaggerSpringMvcPluginCalled_thenReturnsDocketWithSwagger2() {
        // GIVEN - SwaggerConfig instance

        // WHEN - Calling swaggerSpringMvcPlugin
        Docket docket = swaggerConfig.swaggerSpringMvcPlugin();

        // THEN - Verify non-null and correct documentation type
        assertNotNull(docket);
        assertEquals(DocumentationType.SWAGGER_2, docket.getDocumentationType());
    }
}

