import com.bestpractice.api.domain.component.RequestInfoComponent;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import springfox.documentation.spring.web.plugins.Docket;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

public class AppBeanGeneratedAiTests {

    private AppBean.SwaggerConfig.WebMvcConfig webMvcConfig;
    private AuthComponent authComponent;
    private RequestInfoComponent requestInfoComponent;

    @BeforeEach
    public void setUp() throws Exception {
        authComponent = mock(AuthComponent.class);
        requestInfoComponent = new RequestInfoComponent();
        webMvcConfig = new AppBean.SwaggerConfig.WebMvcConfig();

        Field authField = AppBean.SwaggerConfig.WebMvcConfig.class.getDeclaredField("authComponent");
        authField.setAccessible(true);
        authField.set(webMvcConfig, authComponent);

        Field requestInfoField = AppBean.SwaggerConfig.WebMvcConfig.class.getDeclaredField("requestInfo");
        requestInfoField.setAccessible(true);
        requestInfoField.set(webMvcConfig, requestInfoComponent);
    }

    @Test
    public void givenAuthAndRequestInfo_whenInterceptorControllerCalled_thenReturnsControllerInstance() {
        // GIVEN - setup authComponent and requestInfoComponent
        // WHEN - call interceptorController
        InterceptorController controller = webMvcConfig.interceptorController();
        // THEN - verify controller is not null and has expected dependencies
        assertNotNull(controller);
    }

    @Test
    public void givenInterceptorRegistry_whenAddInterceptorsCalled_thenInterceptorIsRegistered() {
        // GIVEN - mock InterceptorRegistry
        InterceptorRegistry registry = mock(InterceptorRegistry.class);
        // WHEN - call addInterceptors
        webMvcConfig.addInterceptors(registry);
        // THEN - verify registry.addInterceptor was called
        verify(registry, times(1)).addInterceptor(any(InterceptorController.class));
    }

    @Test
    public void givenSwaggerConfig_whenSwaggerSpringMvcPluginCalled_thenReturnsDocketInstance() {
        // GIVEN - create SwaggerConfig
        AppBean.SwaggerConfig swaggerConfig = new AppBean.SwaggerConfig();
        // WHEN - call swaggerSpringMvcPlugin
        Docket docket = swaggerConfig.swaggerSpringMvcPlugin();
        // THEN - verify docket is not null
        assertNotNull(docket);
    }
}
