import org.springframework.web.servlet.handler.MappedInterceptor;
import springfox.documentation.spring.web.plugins.Docket;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AppBeanGeneratedAiTests {

    private AppBean.SwaggerConfig.WebMvcConfig webMvcConfig;
    private RequestInfoComponent requestInfoComponent;
    private AuthComponent authComponent;

    @BeforeEach
    void setUp() {
        requestInfoComponent = mock(RequestInfoComponent.class);
        authComponent = mock(AuthComponent.class);
        webMvcConfig = new AppBean.SwaggerConfig.WebMvcConfig() {
            {
                try {
                    java.lang.reflect.Field requestInfoField = AppBean.SwaggerConfig.WebMvcConfig.class.getDeclaredField("requestInfo");
                    requestInfoField.setAccessible(true);
                    requestInfoField.set(this, requestInfoComponent);

                    java.lang.reflect.Field authComponentField = AppBean.SwaggerConfig.WebMvcConfig.class.getDeclaredField("authComponent");
                    authComponentField.setAccessible(true);
                    authComponentField.set(this, authComponent);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        };
    }

    @Test
    void givenAuthAndRequestInfo_whenInterceptorController_thenNotNull() {
        // GIVEN
        // Dependencies are set in setUp

        // WHEN
        InterceptorController interceptorController = webMvcConfig.interceptorController();

        // THEN
        assertNotNull(interceptorController);
    }

    @Test
    void givenInterceptorController_whenAddInterceptors_thenRegistryContainsInterceptor() throws Exception {
        // GIVEN
        InterceptorRegistry registry = new InterceptorRegistry();

        // WHEN
        webMvcConfig.addInterceptors(registry);

        // THEN
        java.lang.reflect.Field interceptorsField = InterceptorRegistry.class.getDeclaredField("interceptors");
        interceptorsField.setAccessible(true);
        List<?> interceptors = (List<?>) interceptorsField.get(registry);
        assertFalse(interceptors.isEmpty());
        assertTrue(interceptors.stream().anyMatch(i -> i instanceof MappedInterceptor));
    }

    @Test
    void givenSwaggerConfig_whenSwaggerSpringMvcPlugin_thenDocketCreated() {
        // GIVEN
        AppBean.SwaggerConfig swaggerConfig = new AppBean.SwaggerConfig();

        // WHEN
        Docket docket = swaggerConfig.swaggerSpringMvcPlugin();

        // THEN
        assertNotNull(docket);
        assertEquals("springfox.documentation.spring.web.plugins.Docket", docket.getClass().getName());
    }
}
